export function makeInvoiceRepository(db) {           // db = injected ORM client
  return {
    async findOverdue(on) {
      const rows = await db.invoice.findMany({ where: { due: { lt: on } } });
      return rows.map(toInvoice);                     // domain objects, never model instances
    },
    async add(invoice) {
      await db.invoice.create(toRow(invoice));        // no commit: caller owns the transaction
    },
  };
}
